      '|Схема пока не замкнута. К машине можно вернуться в любой момент.',
      { end: true },
      '#no',
      '|Сложная машина с модулями магнитного потока. Без хозяйки мастерской её лучше не трогать.',
      { end: true },
      '#done',
      '|Машина ровно гудит. Ток идёт по всей схеме.'
