      'march|Клуб только для боёв... Кто знал, что у подземщиков такие жестокие хобби.',
      'hook|Угу, вообще-то, это круто! Куча детей в них участвует.',
      'march|...Возмутительно. Моё чутьё борца за справедливость начинает покалывать...',
      'hook|Пришли! Вот оно. Кроты этим занимаются, вот кто! ...Но допускаются только дети. Дикий Огонь проводит бои среди взрослых.',
