      'seele|Теперь тут безопасно. Давайте зайдём внутрь.',
      'seele|Мы в детстве играли на улице и всё время получали синяки и ссадины. Вон в том углу должны лежать материалы для таких случаев.',
      'seele|Только надеюсь, монстры их не уничтожили.',
      'bronya|...Мне не показалось.',
      'seele|М-м? О чём ты?',
      'bronya|Это здание, эта игровая площадка... Выглядят очень знакомо.',
      'seele|Что?! Да ладно, Надмирье и Подземье были изолированы друг от друга более десяти лет, здесь не было ни одного воина Среброгривых Стражей. Если бы к нам сюда спустилась принцесса Надмирья - новость разлетелась бы по всем углам.',
      'seele|Подожди, разве что до этого...',
      'bronya|...Да, возможно. Это бы объяснило, почему мои воспоминания так расплывчаты.',
      'bronya|Пошли, мне нужно осмотреться, чтобы убедиться...',
      { obj: 'Поищите припасы на площадке у приюта', at: 'u_rivet2:Я' }
