      'march|Ух ты! Скорее, смотрите! Это Броня! Ч-что? А это Коколия?!',
      'danheng|Нет, это не они. Это должно быть... что-то вроде эха? Какая-то остаточная энергия, воспроизведённая Фрагментумом...',
