      '=Воля хранительницы|Ты - {чужак|чужачка}, и всё же мечтаешь связать свою судьбу с нами... Так тому и быть. Чего терять, если всё давным-давно потеряно...',
      '=Воля хранительницы|Коснись огня Янтаря, Первопроходец. Посмотрим, привлечёт ли Эона твоя воля.',
