      'antonia|...Трусливые людишки. Что-то не припомню, чтобы вы так себя вели с приспешниками Сварога.',
      'miner=Бродяга|Пф, мы не дураки! Рисковать жизнью, сражаясь против роботов? А сами-то! Отрыли огромный кусок геосущности и решили прибрать его к рукам!',
      'antonia|...Только зря потратили время, пытаясь с вами договориться. Пока вы тут шумели, жилу захватили роботы. Теперь мы все в одной лодке.',
      'miner=Бродяга|Чушь! Дикий Огонь увяз в разборках с приспешниками Сварога. Не хотите получить пулю - отдавайте геосущность!',
